import math
# Axial cross-section: triangle with base (-6,0)-(6,0) and apex (0,8).
# Slanted side through (6,0) and (0,8) is 8x + 6y - 48 = 0.
def dist(r):
    # distance from the centre (0, r) to that slanted side
    return abs(6*r - 48) / math.hypot(8, 6)
lo, hi = 0.0, 8.0
f = lambda r: dist(r) - r
for _ in range(200):
    mid = (lo + hi) / 2
    if f(lo) * f(mid) <= 0:
        hi = mid
    else:
        lo = mid
print(round((lo + hi) / 2))
